      // gh-1729 review: the pre-flight is where the armed E1 one-shot
      // pass must ACT (a compaction before the request) — see
      // [_maybeAutoCompact]'s `forceE1Pass`.
      await _maybeAutoCompact(forceE1Pass: true);
