  /// pre-unique-id name (`sh-<n>.log`) is written after this process booted
  /// (see [ShellJobRegistry.onStaleJobLog]): another fa on an OLDER build is
  /// running in this directory and can interleave output into shared files.
  /// Surfaced loudly — this exact skew silently poisoned tool output for a
  /// whole day before anyone found it.
  void _onStaleJobLog(String path) {
    final name = path.split('/').last;
    io.writeln(
      tuiWarning(
        'warning: $name was just written by an older fa build also running '
        'in this directory — its output can interleave with stale job logs. '
        'Restart that fa instance on this binary to fix.',
      ),
    );
    _logDiagnostic('stale old-format job log detected: $path');
  }

  /// Low-disk guard fired at most once per background job (issue #919):
  /// its log writes stopped (free space under the safety threshold), the
  /// job itself keeps running with degraded capture.
  void _onJobLogWarning(String message) {
    io.writeln(tuiWarning('warning: $message'));
    _logDiagnostic('job log guard: $message');
  }

  Future<void> _afterRun() async {
    // A TTSR abort/inject/retry chain may still be in flight when the
    // aborted run settles; persist only once the whole chain completed.
    await _ttsr?.settled;
    _hubCompletePanels();
    await _persistMessages();
    // gh-1590: a run finalize gives the job board a chance to land its
    // snapshot — UNFORCED, inside the persist window: the drain path
    // completes one run per settle notice, and a force here would append
    // one record per reaction run, defeating the coalescing. The final
    // state rides the trailing leg or the shutdown flush instead; when
    // the window is open the gate skips the encode entirely.
    await _persistJobBoard();
    try {
      await _maybeAutoCompact();
    } on CancelledException {
      // Abort during the POST-RUN compaction window (issue #1085 round-4
      // review): the turn has already settled and reported its outcome —
      // rethrowing here would re-enter error handling and print a
      // spurious `error: CancelledException` line over a finished turn.
      // The dim note is the receipt; the next prompt starts clean.
      io.writeln(_style.dim('compaction interrupted'));
    }
  }
}

/// The composer-submit glue for clipboard chips (issue #276) — split out of
/// `agent_cli.dart` to keep it under the repo's 2800-line size gate. Same
/// library (a `part of`), so the extension sees the AgentCli's private
/// members (`_agent`, `_settled`, `_abortRequested`, `_exited`).
part of 'agent_cli.dart';

/// The one-line error panel the submit boundary renders for a throw that
/// escaped a command or settings flow (gh-1787): the exception's message
/// on ONE line. A raw stack trace never reaches the transcript — a
/// multi-line payload (the yaml parser's box, an uncaught-zone dump
/// replayed as data) collapses to its first meaningful line, so frame
/// markers and `<asynchronous suspension>` can never ride the panel.
String submitErrorPanelLine(Object error) {
  // A leading line that IS the bare zone-print header (`Unhandled
  // exception:` — an uncaught-zone dump replayed as data) names nothing;
  // the CAUSE rides the next line. Leading headers are skipped so the
  // panel always carries the error itself; a body that merely mentions
  // the words is content, not boilerplate, and stays.
  var leading = true;
  for (final line in error.toString().split('\n')) {
    final trimmed = line.trim();
    if (trimmed.isEmpty) continue;
    if (leading && trimmed == 'Unhandled exception:') continue;
    leading = false;
    return trimmed;
  }
  return error.runtimeType.toString();
}

/// The TUI submit boundary's containment (gh-1787): runs [body] and
/// reports any throw through [report] — never rethrows. One choke point at
/// `_handleTuiSubmit`: every settings flow reachable from a submit inherits
/// the guard, a failed flow renders the clean one-line error panel
/// (validate-first writes leave the config untouched — nothing to roll
/// back), and the session stays usable.
Future<void> runContainedSubmit(
  Future<void> Function() body,
  void Function(Object error) report,
) async {
  try {
    await body();
  } on Object catch (error) {
    report(error);
  }
}

