  @visibleForTesting
  Future<void> tuiSubmitForTest(String line, List<TuiImageAttachment> images) {
    final controller = _tuiController ?? _createTuiController();
    _tuiController = controller;
    return _handleTuiSubmit(controller, line, images);
  }
}

